<section class="panel table-panel"><div class="table-wrap"><table><thead><tr><th><input type="checkbox"></th><th>CÔNG VIỆC</th><th>DỰ ÁN</th><th>NGƯỜI THỰC HIỆN</th><th>ƯU TIÊN</th><th>TRẠNG THÁI</th><th>THỜI HẠN</th><th></th></tr></thead><tbody>
@forelse($tasks as $task)<tr><td><input type="checkbox"></td><td><a class="task-name" href="{{ route('tasks.edit',$task) }}"><span class="task-check {{ $task->status === 'done' ? 'done' : '' }}">{{ $task->status === 'done' ? '✓' : '' }}</span><strong>{{ $task->title }}</strong></a></td><td><span class="project-chip"><i style="background:#{{ substr(md5($task->project->key),0,6) }}"></i>{{ $task->project->name }}</span></td><td><span class="person"><span class="avatar">{{ mb_substr($task->assignee?->name ?? '?',0,1) }}</span>{{ $task->assignee?->name ?? 'Chưa giao' }}</span></td><td><span class="priority {{ $task->priority }}">● {{ ['low'=>'Thấp','medium'=>'Trung bình','high'=>'Cao','urgent'=>'Khẩn cấp'][$task->priority] ?? $task->priority }}</span></td><td><span class="badge {{ $task->status }}">{{ ['todo'=>'Cần làm','in_progress'=>'Đang làm','review'=>'Đánh giá','done'=>'Hoàn thành'][$task->status] ?? $task->status }}</span></td><td class="{{ $task->due_date?->isPast()&&$task->status!=='done'?'text-danger':'' }}">◷ {{ $task->due_date?->format('d/m/Y') ?? '—' }}</td><td><a class="icon-btn" href="{{ route('tasks.edit',$task) }}">•••</a></td></tr>
